<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN""http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">
<html xmlns="http://www.w3.org/1999/xhtml">
<head>
    <meta http-equiv="Content-Type" content="text/html; charset=gb2312"/>
    <meta name="viewport"
          content="width=device-width, initial-scale=1.0; minimum-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>入网规范管理平台</title></head>
<body style="margin:0 auto; text-align:center;">
<noscript style="color:#536782;"><img src="/a/images/mobile_img/wenhao.png" width="150" height="150"/><br/>对不起，当前浏览器未启用JavaScript！
</noscript>
<script type="text/javascript" src="/tp/js/jquery.164.min.js"></script>
<script type="text/javascript" src="/tp/js/os_browser_info.js"></script>
<a href="javascript:void(0)" onclick="framebusting()" id="framebusting-a" style="display: none">请点击此处跳转到入网页面</a>
<script type="text/javascript">
    function framebusting() {
        if (window.location !== window.top.location) {
            window.top.location = window.location;
        }
    }

    /**
     * 是否客户端打开子界面
     * @returns {boolean}
     */
    function isQtClient() {
        return navigator.userAgent.indexOf('QtWebEngine') !== -1
    }

    /**
     * 判断IP是否是局域网IP
     * @returns {boolean}
     */
    function IsLAN(ip) {
        ip.toLowerCase();
        if(ip=='localhost') return true;
        var a_ip = 0;
        if(ip == "") return false;
        var aNum = ip.split(".");
        if(aNum.length != 4) return false;
        a_ip += parseInt(aNum[0]) << 24;
        a_ip += parseInt(aNum[1]) << 16;
        a_ip += parseInt(aNum[2]) << 8;
        a_ip += parseInt(aNum[3]) << 0;
        a_ip=a_ip>>16 & 0xFFFF;
        return( a_ip>>8 == 0x7F || a_ip>>8 == 0xA || a_ip== 0xC0A8 || (a_ip>=0xAC10 && a_ip<=0xAC1F) );
    }

    (function () {
        //如果是在iframe内, 首先跳出iframe
        try {
            // 如果iframe嵌套，判断是否Qt、或者sso认证成功，则通知父级sso认证成功
            var isIframe = window.location !== window.top.location;
            if (isIframe) {
                if (isQtClient()) {
                    window.parent.postMessage('ssoAuth:success', '*');
                    return;
                }
                if (window.location.search.indexOf('?skipStatus=1') !== -1 && typeof window.parent.ssoAuthSuccessCallback === 'function') {
                    window.parent.ssoAuthSuccessCallback({
                        'data': 'ssoAuth:success'
                    });
                    return;
                }
            }
            framebusting();
        } catch (e) {
            //chrome 68 要求有用户交互才能跳转
            $('#framebusting-a').show();
            return;
        }
        var projectConf = {};
        var url = '';
        var protocol = '';
        var hostname = '';
        var joint = 0;
        $.ajax({
            url: '/phpdir/trade.php?tradecode=project_conf&tradetype=normal&mod=default',
            type: "GET",
            dataType: 'json',
            success: function (data) {
                //console.log('current_ver',document.cookie,read_cookie('current_ver'));
                projectConf = data;
                if (data['joint'] === '1' && lc_device_info.os_kernel.toLowerCase().indexOf('Windows'.toLowerCase()) !== -1 && lc_device_info.is_mobile !== 1) {
                    url = data['windowsUrl'];
                    joint = 1;
                } else {
                    var current_ver = data['entrance_version']['ItemValue'] === 'a2' ? 'a2' : 'a';
                    switch (data['name']) {
                        case 'ssoauth_shihua_2015':
                            // 中石化统一认证项目的跳转地址
                            if (data['thirdAuth'] === '1') {
                                url = "/portal.php" + window.location.search + (window.location.search.indexOf('?') !== -1 ? "&" : "?") + 'cache=' + Math.random();
                            } else {
                                url = "/a/index.html" + window.location.search + (window.location.search.indexOf('?') !== -1 ? "&" : "?") + 'cache=' + Math.random();
                            }
                            break;
                        default :
                            protocol = window.location.protocol;
                            hostname = window.location.host;
                            //检查是否开启了端口映射
                            var re = /^(1\d{2}|2[0-4]\d|25[0-5]|[1-9]\d|[0-9])\.((1\d{2}|2[0-4]\d|25[0-5]|[1-9]\d|\d)\.){2}(1\d{2}|2[0-4]\d|25[0-5]|[1-9]\d|\d)$/;
                            if(re.test(window.location.hostname)){ //通过IP访问
                                if(!IsLAN(window.location.hostname)){ //如果是端口映射则不做协议和端口切换
                                    url = protocol + '//' + hostname + "/" + current_ver + "/index.html" + window.location.search + (window.location.search.indexOf('?') !== -1 ? "&" : "?") + 'cache=' + Math.random();
                                    break;
                                }
                            }else{ //通过域名访问
                                url = protocol + '//' + hostname + "/" + current_ver + "/index.html" + window.location.search + (window.location.search.indexOf('?') !== -1 ? "&" : "?") + 'cache=' + Math.random();
                                break;
                            }

                            //根据配置走https或http，端口使用默认的443或80
                            protocol = data['protocol'];
                            var http_port = data['http_port'] || 80
                            var https_port = data['https_port'] || 443
                            hostname = window.location.hostname;
                            if (lc_device_info.os_kernel === 'Windows XP' || lc_device_info.browser_version === 'IE 6.0' || lc_device_info.isMacCNA) {
                                //xp 继续走http
                                protocol = 'http:';
                            }
                            if (current_ver === 'a2') {
                                //a2继续走http
                                protocol = 'http:';
                            }

                            var isHttps = protocol === 'https:';
                            var port = isHttps ? https_port : http_port;
                            hostname += ':' + port
                            url = protocol + '//' + hostname + "/" + current_ver + "/index.html" + window.location.search + (window.location.search.indexOf('?') !== -1 ? "&" : "?") + 'cache=' + Math.random();
                    }
                }
                // 由于ios内嵌浏览器在同步场景会有跨域问题，改成异步后，这里请求成功后处理
                //分布式DASM不支持入网流程，直接跳转到管理员登录界面
                if (projectConf['deviceType'] === 'dasm' || projectConf['deviceType'] === 'dblb') {
                    window.location.href = '/admin';
                } else {
                    if (lc_device_info.is_mobile === 1) {
                        /**  huangwei wince重定向 begin  ***/
                        if (lc_device_info.os_kernel === 'Windows CE' && lc_device_info.os_platform === 'Windows CE') {
                            window.location.href = "/a/wince/wince_auth.html";
                        } else {
                            window.location.href = protocol + '//' + hostname + "/a/mobile.php" + window.location.search + window.location.hash;
                        }
                        /**  huangwei wince重定向 end  ***/
                    } else {
                        //PC流程
                        if (joint === 0) {
                            var search = window.location.search;
                            if (search.indexOf('forbit=1') !== -1 || search.indexOf('forbid=1') !== -1) {
                                search = search.replace('forbid=1', 'forbid=0');
                                search = search.replace('forbit=1', 'forbit=0');
                                // 记录是从forbid页面跳转过去的
                                window.location.href = protocol + '//' + hostname + '/access/ui/index.html' + search + window.location.hash + '#/access/forbid';
                            } else {
                                window.location.href = protocol + '//' + hostname + '/access/ui/index.html' + search + window.location.hash
                            }
                        } else {
                            window.location.href = url;
                        }
                    }
                }
            },
            error: function (data) {
                //alert(JSON.stringify(data));
            }
        });

    })();
</script>
</body>
</html>

