=== /a/js/common/scc/ver.js ===
var STATIC_CACHE_CONTROL_VER = '1788662847-484';

=== /a/js/common/scc/scc.js ===
(function (win) {
    var scc = typeof win.scc === 'undefined' ? {} : win.scc;

    function isArray (v) {
        return Object.prototype.toString.call(v) === '[object Array]';
    }

    function getVer() {
        if (typeof STATIC_CACHE_CONTROL_VER !== 'undefined') {
            return STATIC_CACHE_CONTROL_VER;
        } else {
            try {
                return STATIC_CACHE_CONTROL_VER = window.parent.scc.getVer()
            } catch (e) {}
        }
        STATIC_CACHE_CONTROL_VER = (new Date()).getTime();
        return STATIC_CACHE_CONTROL_VER
    }

    scc.getVer = getVer;

    scc.load = function (srcs) {
        srcs = isArray(srcs) ? srcs : [srcs];
        var html = '';
        for (var i = 0; i < srcs.length; i++) {
            var src = srcs[i],
                parts = src.split('?'),
                fileParts = parts[0].split('.'),
                ext = fileParts[fileParts.length - 1];

            src += (parts.length > 1 ? '&scc=' : '?scc=') + getVer();

            if (ext === 'js') {
                html += '<script type="text/javascript" src="' + src +'"></script>'
            } else if (ext === 'css') {
                html += '<link rel="stylesheet" href="' + src + '">'
            }
        }
        win.document.write(html);
    };
    scc.addTo = function (url) {
        if (typeof url === 'string') {
            return url + (url.indexOf('?') === -1 ? '?scc=' : '?scc=') + getVer()
        }
        return url
    };

    win.scc = scc;
})(window);

