            _ascId = (_config.AscId ?? "").Trim();
        }

        public ServerSnapshot GetServerSnapshot(bool refresh)
        {
            if (refresh || _server == null || (DateTime.Now - _serverTime).TotalMinutes > 5)
            {
                _server = FetchServerInfo();
                _serverTime = DateTime.Now;
