            note.AutoSize = false;
            note.Location = new Point(24, 378);
            note.Size = new Size(592, 22);
            Controls.Add(note);

            Panel footer = new Panel();
            footer.Dock = DockStyle.Bottom;
            footer.Height = 62;
            footer.BackColor = Color.FromArgb(248, 249, 251);
            Controls.Add(footer);

